enum State { OFF, SLOW, FAST };
State s = OFF;
const int BTN = {{button_pin}};
const int LED = {{led_pin}};
unsigned long last = 0;
int lastBtn = HIGH;

void setup() {
  pinMode(BTN, INPUT_PULLUP);
  pinMode(LED, OUTPUT);
}

void loop() {
  int r = digitalRead(BTN);
  if (lastBtn == HIGH && r == LOW) {
    s = (State)((s + 1) % 3);
    delay(150);
  }
  lastBtn = r;
  unsigned long now = millis();
  int period = (s == OFF) ? 0 : (s == SLOW ? 800 : 150);
  if (period && now - last > period) { last = now; digitalWrite(LED, !digitalRead(LED)); }
  if (!period) digitalWrite(LED, LOW);
}
